(()=>{const e=async e=>{const t=document.querySelector("#content");switch(e.status){case 200:t.innerHTML="<b>Success</b>";break;case 201:t.innerHTML="<b>Created</b>";break;case 204:return void(t.innerHTML="<b>Updated (No Content)</b>");case 404:t.innerHTML="<b>Not Found</b>";break;default:t.innerHTML="Error code not implemented by client."}if(!e.body)return;let n=await e.json();n.message&&(t.innerHTML+=`<p>${JSON.stringify(n.message)}</p>`)};window.onload=()=>{document.querySelector("#nameForm").onsubmit=t=>{t.preventDefault();const n=`/addUser?name=${document.querySelector("#nameField").value}&age=${document.querySelector("#ageField").value}`;return fetch(n,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"}}).then(t=>e(t)),!1},document.querySelector("#userForm").onsubmit=t=>{t.preventDefault();const n=document.querySelector("#urlField").value,o={method:document.querySelector("#methodSelect").value,headers:{"Content-Type":"application/json",Accept:"application/json"}};return fetch(n,o).then(t=>e(t)),!1}}})();